2|///
3|/// Publishes Home Assistant discovery configs for:
4|/// - Presence sensor (available / busy / dnd / away)
5|/// - Microphone sensor (speaking / silent / muted / off)
6|/// - Binary sensors (in-call, screen-sharing, camera)
7|/// - Buttons (toggle-mute, toggle-video, toggle-hand-raise)
8|///
9|/// Mirrors the Teams-for-Linux homeAssistantDiscovery.js pattern:
10|/// sensors for state, buttons for one-shot actions.
11|
12|use serde_json::json;
13|use tracing::info;
14|
15|use crate::config::HomeAssistantConfig;
16|use crate::MqttClient;
17|
18|/// Home Assistant auto-discovery payload generator.
19|pub struct HaDiscovery {
20|    config: HomeAssistantConfig,
21|}
22|
23|impl HaDiscovery {
24|    /// Create a new discovery config generator.
25|    pub fn new(config: HomeAssistantConfig) -> Self {
26|        Self { config }
27|    }
28|
29|    /// Publish all Home Assistant discovery configs via the MQTT client.
30|    pub async fn publish_all(&self, client: &MqttClient) -> Result<(), crate::MqttError> {
31|        if !self.config.enabled {
32|            return Ok(());
33|        }
34|
35|        let prefix = &self.config.discovery_prefix;
36|        let device_name = &self.config.device_name;
37|        let topic_prefix = client.topic_prefix();
38|        let device_id = format!("crabjar-{topic_prefix}");
39|
40|        // Helper: build common device metadata
