{"content": "1|const logger = require('electron-log');
2|
3|class GraphApiClient {
4|  constructor(config = {}) {
5|    this.config = config;
6|    this.enabled = config.graphApi?.enabled ?? false;
7|    this.baseUrl = 'https://graph.microsoft.com/v1.0';
8|    this.currentToken = null;
9|    this.tokenExpiry = null;
10|    this.cachedSenderInfo = null;
11|
12|    logger.info('[GRAPH_API] GraphApiClient initialized', {
13|      enabled: this.enabled,
14|      baseUrl: this.baseUrl
15|    });
16|  }
17|
18|  initialize(mainWindow) {
19|    this.mainWindow = mainWindow;
20|    logger.debug('[GRAPH_API] Main window set');
21|  }
22|
23|  isEnabled() {
24|    return this.enabled;
25|  }
26|
27|  async acquireToken(forceRefresh = false) {
28|    try {
29|      if (!this.mainWindow?.webContents) {
30|        logger.warn('[GRAPH_API] Main window not initialized');
31|        return { success: false, error: 'Main window not initialized' };
32|      }
33|
34|      if (!forceRefresh && this.currentToken && this.tokenExpiry) {
35|        const now = Date.now();
36|        const expiryTime = new Date(this.tokenExpiry).getTime();
37|        const timeUntilExpiry = expiryTime - now;
38|
39|        // Require 5-minute buffer before expiry to avoid race conditions
40|        if (timeUntilExpiry > 5 * 60 * 1000) {
41|          logger.debug('[GRAPH_API] Using cached token', {
42|            timeUntilExpiry: Math.floor(timeUntilExpiry / 1000) + 's'
43|          });
44|          return {
45|            success: true,
46|            token: this.currentToken,
47|            fromCache: true,
48|            expiry: this.tokenExpiry
49|          };
50|        }
51|      }
52|
53|      const result = await this.mainWindow.webContents.executeJavaScript(`
54|        (async () => {
55|          if (window.teamsForLinuxReactHandler && typeof window.teamsForLinuxReactHandler.acquireToken === 'function') {
56|            return await window.teamsForLinuxReactHandler.acquireToken('https://graph.microsoft.com', {
57|              forceRenew: ${forceRefresh}
58|            });
59|          } else {
60|            return { success: false, error: 'ReactHandler not available' };
61|          }
62|        })()
63|      `);
64|
65|      if (result?.success && result?.token) {
66|        this.currentToken = result.token;
67|        this.tokenExpiry = result.expiry;
68|
69|        logger.debug('[GRAPH_API] Token acquired successfully', {
70|          fromCache: result.fromCache,
71|          expiry: result.expiry
72|        });
73|
74|        return result;
75|      } else {
76|        logger.warn('[GRAPH_API] Token acquisition failed', result);
77|        return result || { success: false, error: 'Unknown error' };
78|      }
79|
80|    } catch (error) {
81|      logger.error('[GRAPH_API] Token acquisition error:', error);
82|      return {
83|        success: false,
84|        error: error.message || error.toString()
85|      };
86|    }
87|  }
88|
89|  async makeRequest(endpoint, options = {}) {
90|    try {
91|      if (!this.enabled) {
92|        logger.warn('[GRAPH_API] Graph API is disabled');
93|        return { success: false, error: 'Graph API is disabled' };
94|      }
95|
96|      const tokenResult = await this.acquireToken();
97|      if (!tokenResult.success || !tokenResult.token) {
98|        return { success: false, error: 'Failed to acquire token' };
99|      }
100|
101|      const url = endpoint.startsWith('http') ? endpoint : `${this.baseUrl}${endpoint}`;
102|      const method = options.method || 'GET';
103|
104|      logger.debug('[GRAPH_API] Making request', { method, endpoint: url });
105|
106|      const response = await fetch(url, {
107|        method,
108|        headers: {
109|          'Authorization': `Bearer ${tokenResult.token}`,
110|          'Content-Type': 'application/json',
111|          ...options.headers
112|        },
113|        ...(options.body && { body: JSON.stringify(options.body) })
114|      });
115|      const responseText = await response.text();
116|
117|      let data = null;
118|      if (responseText) {
119|        try {
120|          data = JSON.parse(responseText);
121|        } catch (parseError) {
122|          // Intentionally catch - continue with null data for non-JSON responses (e.g., 204 No Content)
123|          logger.warn('[GRAPH_API] Failed to parse response as JSON', {
124|            status: response.status,
125|            textPreview: responseText.substring(0, 100),
126|            parseError: parseError.message
127|          });
128|        }
129|      }
130|
131|      if (response.ok) {
132|        logger.debug('[GRAPH_API] Request successful', {
133|          status: response.status,
134|          endpoint: url
135|        });
136|        return { success: true, data };
137|      } else {
138|        logger.warn('[GRAPH_API] Request failed', {
139|          status: response.status,
140|          error: data?.error
141|        });
142|        return {
143|          success: false,
144|          error: data?.error?.message || responseText || 'API request failed',
145|          status: response.status,
146|          data
147|        };
148|      }
149|
150|    } catch (error) {
151|      logger.error('[GRAPH_API] Request error:', error);
152|      return {
153|        success: false,
154|        error: error.message || error.toString()
155|      };
156|    }
157|  }
