159|  _escapeHtml(text) {
160|    return text
161|      .replaceAll('&', '&amp;')
162|      .replaceAll('<', '&lt;')
163|      .replaceAll('>', '&gt;')
164|      .replaceAll('"', '&quot;')
165|      .replaceAll("'", '&#39;');
