167|
168|  _buildODataQuery(options) {
169|    const params = new URLSearchParams();
170|    const supportedParams = {
171|      startDateTime: 'startDateTime',
172|      endDateTime: 'endDateTime',
173|      top: '$top',
174|      select: '$select',
175|      filter: '$filter',
176|      orderby: '$orderby',
177|      skip: '$skip',
178|      count: '$count',
179|      search: '$search',
180|      expand: '$expand'
181|    };
182|
183|    for (const [key, value] of Object.entries(options)) {
184|      if (supportedParams[key] && value !== undefined && value !== null) {
185|        params.append(supportedParams[key], value);
186|      }
187|    }
188|
189|    return params.toString();
190|  }
