274|      ...options
275|    };
276|
277|    if (query) {
278|      // Escape quotes and backslashes in search query
279|      const escapedQuery = query
280|        .replaceAll('\\', String.raw`\\`)
281|        .replaceAll('"', String.raw`\"`);
282|      queryOptions.search = `"${escapedQuery}"`;
283|    }
