291|  /** Resolve or create a 1:1 chat with a user via Teams internal services */
292|  async resolveConversation(recipientUserId) {
293|    try {
294|      if (!this.enabled) {
295|        return { success: false, error: 'Graph API is disabled' };
296|      }
297|
298|      if (!this.mainWindow?.webContents) {
299|        return { success: false, error: 'Main window not initialized' };
300|      }
301|
302|      // Validate recipientUserId is a GUID to prevent injection
303|      const guidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
304|      if (!guidRegex.test(recipientUserId)) {
305|        return { success: false, error: 'Invalid user ID format' };
306|      }
307|
308|      const recipientMri = `8:orgid:${recipientUserId}`;
309|
310|      // Step 1: Use Teams' entityCommanding to ensure the 1:1 chat exists
311|      await this.mainWindow.webContents.executeJavaScript(`
312|        (async () => {
313|          const handler = window.teamsForLinuxReactHandler;
314|          if (!handler) return;
315|          const coreServices = handler._getTeams2CoreServices();
316|          if (!coreServices) return;
317|          const chatCommanding = coreServices.entityCommanding?.chat;
318|          if (chatCommanding) await chatCommanding.chatWithUsers([${JSON.stringify(recipientMri)}]);
319|        })()
320|      `);
321|
322|      // Wait for Teams to process the navigation
323|      await new Promise(r => setTimeout(r, 2000));
324|
325|      // Step 2: Collect candidate thread IDs from the DOM
326|      // Scan specific attributes to reduce performance impact
327|      const candidates = await this.mainWindow.webContents.executeJavaScript(String.raw`
328|        (() => {
329|          const ids = new Set();
330|          const maxElements = 1000; // Cap to prevent UI hangs
331|          let count = 0;
332|
333|          // Target specific attributes likely to contain chat IDs
334|          const attributesToCheck = ['id', 'data-tid', 'aria-label', 'data-convid'];
335|          const elements = document.querySelectorAll('[id], [data-tid], [aria-label], [data-convid]');
336|
337|          for (const el of elements) {
338|            if (++count > maxElements) break;
339|
340|            for (const attrName of attributesToCheck) {
341|              const attrValue = el.getAttribute(attrName);
342|              if (attrValue && attrValue.includes('19:')) {
343|                const matches = attrValue.matchAll(/19:[a-zA-Z0-9_-]+@(?:thread\.v2|unq\.gbl\.spaces)/gi);
344|                for (const m of matches) {
345|                  if (!m[0].includes('meeting_')) ids.add(m[0]);
346|                }
347|              }
348|            }
349|          }
350|          return [...ids];
351|        })()
352|      `);
353|
354|      logger.info('[GRAPH_API] Found candidate chat IDs', { count: candidates?.length });
355|
356|      if (!candidates?.length) {
357|        return { success: false, error: 'No chat thread IDs found' };
358|      }
359|
360|      // Step 3: Check each candidate's members to find the 1:1 chat with the target user
361|      for (const chatId of candidates) {
362|        const membersResult = await this.makeRequest(`/chats/${encodeURIComponent(chatId)}/members`);
363|        if (!membersResult.success || !membersResult.data?.value) continue;
364|
365|        const members = membersResult.data.value;
366|
367|        // Skip group chats — a 1:1 chat has exactly 2 members
368|        if (members.length !== 2) {
369|          continue;
370|        }
371|
372|        const hasRecipient = members.some(
373|          member => member.userId === recipientUserId
374|        );
375|
376|        if (hasRecipient) {
377|          logger.info('[GRAPH_API] Conversation resolved via member check', {
378|            chatId: chatId.substring(0, 40) + '...',
379|            checkedCount: candidates.indexOf(chatId) + 1
380|          });
381|          return { success: true, conversationId: chatId };
382|        }
383|      }
384|
385|      logger.warn('[GRAPH_API] No chat found containing target user');
386|      return { success: false, error: 'Could not find a chat with this user. You may need to start a conversation in Teams first.' };
387|    } catch (error) {
388|      logger.error('[GRAPH_API] Conversation resolution error:', error);
389|      return { success: false, error: error.message || error.toString() };
390|    }
391|  }
392|
393|  /** Send a chat message via Graph API (uses ChatMessage.Send scope) */
394|  async sendChatMessage(chatId, content) {
395|    try {
396|      const result = await this.makeRequest(`/chats/${encodeURIComponent(chatId)}/messages`, {
397|        method: 'POST',
398|        body: {
399|          body: {
400|            content: content,
401|            contentType: 'text'
402|          }
403|        }
404|      });
405|
406|      if (result.success) {
407|        logger.info('[GRAPH_API] Chat message sent via Graph API', {
408|          chatId: chatId?.substring(0, 30) + '...'
409|        });
410|        return { success: true };
411|      }
412|
413|      logger.warn('[GRAPH_API] Send message failed', {
414|        chatId: chatId?.substring(0, 30) + '...',
415|        status: result.status,
416|        error: result.error
417|      });
418|      return result;
419|    } catch (error) {
420|      logger.error('[GRAPH_API] Send message error:', error);
421|      return { success: false, error: error.message || error.toString() };
422|    }
423|  }
424|
425|  /** Send a chat message to a user (orchestrates resolve + send) */
426|  async sendChatMessageToUser(contactInfo, content) {
427|    try {
428|      if (!this.enabled) {
429|        return { success: false, error: 'Graph API is disabled' };
430|      }
431|
432|      // Resolve conversation
433|      const conversationResult = await this.resolveConversation(contactInfo.userId);
434|      if (!conversationResult.success) {
435|        return conversationResult;
436|      }
437|
438|      // Send message via Graph API
439|      return await this.sendChatMessage(conversationResult.conversationId, content);
440|    } catch (error) {
441|      logger.error('[GRAPH_API] sendChatMessageToUser error:', error);
442|      return { success: false, error: error.message || error.toString() };
443|    }
444|  }
