3|const logger = require('electron-log');
4|
5|/**
6| * Register all Graph API IPC handlers
7| * @param {object} ipcMain - Electron ipcMain module
8| * @param {object} graphApiClient - GraphApiClient instance (can be null if disabled)
9| */
10|function registerGraphApiHandlers(ipcMain, graphApiClient) {
11|  const notEnabled = { success: false, error: 'Graph API not enabled' };
12|
13|  // Get current user profile from Microsoft Graph API
14|  ipcMain.handle('graph-api-get-user-profile', async () => {
15|    if (!graphApiClient) return notEnabled;
16|    try {
17|      return await graphApiClient.getUserProfile();
18|    } catch (error) {
19|      logger.error('[GRAPH_API] getUserProfile failed:', { message: error.message });
20|      return { success: false, error: error.message };
21|    }
22|  });
23|
24|  // Get calendar events with optional OData query options
25|  ipcMain.handle('graph-api-get-calendar-events', async (_event, options) => {
26|    if (!graphApiClient) return notEnabled;
27|    try {
28|      return await graphApiClient.getCalendarEvents(options);
29|    } catch (error) {
30|      logger.error('[GRAPH_API] getCalendarEvents failed:', { message: error.message });
31|      return { success: false, error: error.message };
32|    }
33|  });
34|
35|  // Get calendar view for a specific time range
36|  ipcMain.handle('graph-api-get-calendar-view', async (_event, startDateTime, endDateTime, options) => {
37|    if (!graphApiClient) return notEnabled;
38|    try {
39|      return await graphApiClient.getCalendarView(startDateTime, endDateTime, options);
40|    } catch (error) {
41|      logger.error('[GRAPH_API] getCalendarView failed:', { message: error.message });
42|      return { success: false, error: error.message };
43|    }
44|  });
45|
46|  // Create a new calendar event
47|  ipcMain.handle('graph-api-create-calendar-event', async (_event, event) => {
48|    if (!graphApiClient) return notEnabled;
49|    try {
50|      return await graphApiClient.createCalendarEvent(event);
51|    } catch (error) {
52|      logger.error('[GRAPH_API] createCalendarEvent failed:', { message: error.message });
53|      return { success: false, error: error.message };
54|    }
55|  });
56|
57|  // Get mail messages with optional OData query options
58|  ipcMain.handle('graph-api-get-mail-messages', async (_event, options) => {
59|    if (!graphApiClient) return notEnabled;
60|    try {
61|      return await graphApiClient.getMailMessages(options);
62|    } catch (error) {
63|      logger.error('[GRAPH_API] getMailMessages failed:', { message: error.message });
64|      return { success: false, error: error.message };
65|    }
66|  });
67|
68|  // Search people using People API (for Quick Chat feature)
69|  ipcMain.handle('graph-api-search-people', async (_event, query, options) => {
70|    if (!graphApiClient) return notEnabled;
71|    try {
72|      return await graphApiClient.searchPeople(query, options);
73|    } catch (error) {
74|      logger.error('[GRAPH_API] searchPeople failed:', { message: error.message });
75|      return { success: false, error: error.message };
76|    }
77|  });
78|
79|  // Send a chat message to a user via Graph API
80|  ipcMain.handle('graph-api-send-chat-message', async (_event, contactInfo, content) => {
81|    if (!graphApiClient) return notEnabled;
82|    if (!contactInfo || typeof contactInfo.userId !== 'string' || !contactInfo.userId.trim()) {
83|      return { success: false, error: 'Invalid contact info: userId required' };
84|    }
85|    if (typeof content !== 'string' || !content.trim()) {
86|      return { success: false, error: 'Message content cannot be empty' };
87|    }
88|    try {
89|      return await graphApiClient.sendChatMessageToUser(contactInfo, content.trim());
90|    } catch (error) {
91|      logger.error('[GRAPH_API] sendChatMessage failed:', { message: error.message });
92|      return { success: false, error: error.message };
93|    }
94|  });
95|
96|  logger.debug('[GRAPH_API] IPC handlers registered', {
97|    channels: 7,
98|    enabled: !!graphApiClient
99|  });
100|}
101|
102|module.exports = { registerGraphApiHandlers };
