{"content": "1|const { app, ipcMain } = require('electron');
2|
3|/**
4| * MQTT Media Status Service
5| *
6| * Bridges IPC events from renderer process (WebRTC monitoring, call state)
7| * to MQTT broker for home automation integration.
8| *
9| * Publishes to topics:
10| * - {topicPrefix}/camera - Camera on/off state (not yet wired)
11| * - {topicPrefix}/microphone - Microphone state: 'speaking' | 'silent' | 'muted' | 'off'
12| * - {topicPrefix}/in-call - Active call state
13| * - {topicPrefix}/screen-sharing - Screen sharing active state
14| */
15|class MQTTMediaStatusService {
16|	#mqttClient;
17|	#topicPrefix;
18|
19|	constructor(mqttClient, config) {
20|		this.#mqttClient = mqttClient;
21|		this.#topicPrefix = config.mqtt.topicPrefix;
22|	}
23|
24|	initialize() {
25|		// Publish MQTT status when camera state changes
26|		ipcMain.on('camera-state-changed', this.#handleCameraChanged.bind(this));
27|		// Publish MQTT status when microphone state changes
28|		ipcMain.on('microphone-state-changed', this.#handleMicrophoneChanged.bind(this));
29|
30|		// Publish MQTT status when screen sharing starts
31|		ipcMain.on('screen-sharing-started', () => this.#handleScreenSharingChanged(true));
32|		// Publish MQTT status when screen sharing stops
33|		ipcMain.on('screen-sharing-stopped', () => this.#handleScreenSharingChanged(false));
34|
35|		app.on('teams-call-connected', this.#handleCallConnected.bind(this));
36|		app.on('teams-call-disconnected', this.#handleCallDisconnected.bind(this));
37|
38|		console.info('[MQTTMediaStatusService] Initialized');
39|	}
40|
41|	async #handleCallConnected() {
42|		const topic = `${this.#topicPrefix}/in-call`;
43|		await this.#mqttClient.publish(topic, 'true', { retain: true });
44|		console.debug('[MQTTMediaStatusService] Call connected, published to', topic);
45|	}
46|
47|	async #handleCallDisconnected() {
48|		const topic = `${this.#topicPrefix}/in-call`;
49|		await this.#mqttClient.publish(topic, 'false', { retain: true });
50|		console.debug('[MQTTMediaStatusService] Call disconnected, published to', topic);
51|	}
52|
53|	async #handleCameraChanged(event, enabled) {
54|		const topic = `${this.#topicPrefix}/camera`;
55|		await this.#mqttClient.publish(topic, String(enabled), { retain: true });
56|		console.debug('[MQTTMediaStatusService] Camera state changed to', enabled, 'published to', topic);
57|	}
58|
59|	async #handleMicrophoneChanged(event, state) {
60|		const topic = `${this.#topicPrefix}/microphone`;
61|		await this.#mqttClient.publish(topic, state, { retain: true });
62|		console.debug('[MQTTMediaStatusService] Microphone state changed to', state, 'published to', topic);
63|	}
64|
65|	async #handleScreenSharingChanged(isSharing) {
66|		const topic = `${this.#topicPrefix}/screen-sharing`;
67|		await this.#mqttClient.publish(topic, String(isSharing), { retain: true });
68|		const state = isSharing ? 'started' : 'stopped';
69|		console.debug(`[MQTTMediaStatusService] Screen sharing ${state}, published to`, topic);
70|	}
71|}
72|
73|module.exports = MQTTMediaStatusService;
